def _env_int(name: str, default: int) -> int:
    v = os.environ.get(name)
    if v is None or str(v).strip() == "":
        return default
    try:
        return int(v)
    except Exception:
        try:
            return int(float(v))
        except Exception:
            return default

def _env_float(name: str, default: float) -> float:
    v = os.environ.get(name)
    if v is None or str(v).strip() == "":
        return default
    try:
        return float(v)
    except Exception:
        return default

def _env_bool(name: str, default: bool) -> bool:
    v = os.environ.get(name)
    if v is None or str(v).strip() == "":
        return default
    s = str(v).strip().lower()
    if s in ("1", "true", "yes", "y", "on"):
        return True
    if s in ("0", "false", "no", "n", "off"):
        return False
    return default

def _resolve_api_key() -> str:
    preferred = [
        "ZAI_API_KEY", "ZHIPUAI_API_KEY", "BIGMODEL_API_KEY", "BIGMODEL_KEY",
        "OPENAI_API_KEY", "API_KEY", "bigmodel.cr", "BIGMODEL.CR",
    ]
    for k in preferred:
        v = os.environ.get(k)
        if v and v.strip():
            return v.strip()
    for k, v in os.environ.items():
        lk = k.lower()
        if any(x in lk for x in ("bigmodel", "zhipu", "zai")) and "key" in lk and v and v.strip():
            return v.strip()
    for k, v in os.environ.items():
        lk = k.lower()
        if lk.startswith("bigmodel") and v and v.strip():
            return v.strip()
    return ""

