def _pg_dsn() -> str:
    if "PGCHANNELBINDING" in os.environ:
        del os.environ["PGCHANNELBINDING"]
    url = os.environ.get("DATABASE_URL") or os.environ.get("POSTGRES_URL") or os.environ.get("POSTGRESQL_URL") or os.environ.get("PGURL") or os.environ.get("NEON_DATABASE_URL") or os.environ.get("NEON_URL")
    if url and url.strip():
        u = url.strip()
        if "channel_binding=" in u:
            u = re.sub(r"channel_binding=[^& ]+", "", u).replace("  ", " ").strip()
        return u
    defaults = _pg_defaults()
    host = os.environ.get("PGHOST") or defaults["PGHOST"]
    dbname = os.environ.get("PGDATABASE") or defaults["PGDATABASE"]
    user = os.environ.get("PGUSER") or defaults["PGUSER"]
    password = os.environ.get("PGPASSWORD") or defaults["PGPASSWORD"]
    port = os.environ.get("PGPORT")
    sslmode = os.environ.get("PGSSLMODE") or defaults["PGSSLMODE"]
    connect_timeout = _env_int("PGCONNECT_TIMEOUT", 7)
    appname = os.environ.get("PGAPPNAME") or "bigmodel-flask"
    parts = [
        f"host={host}", f"dbname={dbname}", f"user={user}",
        f"password={password}", f"sslmode={sslmode}",
        f"application_name={appname}", f"connect_timeout={int(connect_timeout)}",
    ]
    if port and str(port).strip():
        parts.append(f"port={str(port).strip()}")
    return " ".join(parts)

def _db_enabled() -> bool:
    if not _env_bool("DB_ENABLED", True):
        return False
    if _env_bool("DB_DISABLED", False) or _env_bool("DISABLE_DB", False):
        return False
    return True

def _db_close_pool() -> None:
    global _db_pool
    with _db_lock:
        pool = _db_pool
        _db_pool = None
    if pool is not None:
        try:
            pool.closeall()
        except Exception:
            pass

def _register_shutdown() -> None:
    atexit.register(_db_close_pool)
    try:
        signal.signal(signal.SIGTERM, lambda *_: _db_close_pool())
    except Exception:
        pass
    try:
        signal.signal(signal.SIGINT, lambda *_: _db_close_pool())
    except Exception:
        pass

_register_shutdown()

def _db_can_retry_now() -> bool:
    now = time.time()
    if _db_next_retry_ts == 0.0:
        return True
    return now >= _db_next_retry_ts

def _set_db_retry_backoff() -> None:
    global _db_next_retry_ts
    now = time.time()
    base = _env_float("DB_RETRY_BASE_SECONDS", 5.0)
    cap = _env_float("DB_RETRY_CAP_SECONDS", 120.0)
    prev = max(0.0, _db_next_retry_ts - now)
    next_delay = base if prev <= 0.0 else min(cap, prev * 2.0)
    _db_next_retry_ts = now + next_delay

def _db_init_pool() -> Optional[Any]:
    global _db_pool, _db_last_init_error, _db_next_retry_ts
    if not _db_enabled() or not _pg_available:
        return None
    if _db_pool is not None:
        return _db_pool
    if not _db_can_retry_now():
        return None
    with _db_lock:
        if _db_pool is not None:
            return _db_pool
        if not _db_can_retry_now():
            return None
        try:
            minconn = max(0, _env_int("PGPOOL_MIN", 1))
            maxconn = max(1, _env_int("PGPOOL_MAX", 8))
            if minconn > maxconn:
                minconn = maxconn
            dsn = _pg_dsn()
            pool = ThreadedConnectionPool(minconn, maxconn, dsn=dsn)
            conn = pool.getconn()
            try:
                conn.autocommit = True
                with conn.cursor() as cur:
                    cur.execute(
                        "CREATE TABLE IF NOT EXISTS chat_logs ("
                        "id BIGSERIAL PRIMARY KEY,"
                        "created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),"
                        "remote_addr TEXT,"
                        "user_agent TEXT,"
                        "model TEXT,"
                        "request JSONB NOT NULL,"
                        "reply TEXT,"
                        "reasoning TEXT,"
                        "tool_calls JSONB,"
                        "web_search JSONB,"
                        "parsed_files JSONB,"
                        "error TEXT)"
                    )
                    cur.execute("CREATE INDEX IF NOT EXISTS chat_logs_created_at_idx ON chat_logs (created_at DESC)")
                    cur.execute("CREATE INDEX IF NOT EXISTS chat_logs_model_idx ON chat_logs (model)")
            finally:
                pool.putconn(conn)
            _db_pool = pool
            _db_last_init_error = None
            _db_next_retry_ts = 0.0
            return _db_pool
        except Exception as e:
            _db_pool = None
            _db_last_init_error = str(e)
            _set_db_retry_backoff()
            return None

def _get_db_pool() -> Optional[Any]:
    return _db_pool if _db_pool is not None else _db_init_pool()

def _db_log_chat(model: str, req_json: Dict[str, Any], reply: Optional[str], reasoning: Optional[str], tool_calls: Optional[Any], web_search: List[Dict[str, Any]], parsed_files_meta: List[Dict[str, Any]], error: Optional[str], remote_addr: Optional[str], user_agent: Optional[str]) -> None:
    pool = _get_db_pool()
    if pool is None:
        return
    max_req_chars = _env_int("MAX_DB_REQUEST_CHARS", 400000)
    max_text = _env_int("MAX_DB_TEXT_CHARS", 100000)
    max_err = _env_int("MAX_DB_ERROR_CHARS", 20000)
    def _safe_request_obj(obj: Any) -> Any:
        if obj is None:
            return {}
        try:
            s = json.dumps(obj, ensure_ascii=False, separators=(",", ":"))
            if len(s) <= max_req_chars:
                return obj
            return {"truncated": True, "raw": s[:max_req_chars]}
        except Exception:
            try:
                s2 = str(obj)
                return {"truncated": True, "raw": s2[:max_req_chars]}
            except Exception:
                return {"truncated": True, "raw": None}
    safe_req = _safe_request_obj(req_json)
    reply_out = reply if reply is None or len(reply) <= max_text else reply[:max_text]
    reasoning_out = reasoning if reasoning is None or len(reasoning) <= max_text else reasoning[:max_text]
    error_out = error if error is None or len(error) <= max_err else error[:max_err]
    tool_calls_out = tool_calls
    try:
        if tool_calls_out is not None:
            json.dumps(tool_calls_out, ensure_ascii=False)
    except Exception:
        tool_calls_out = {"unserializable": True}
    conn = pool.getconn()
    try:
        conn.autocommit = True
        with conn.cursor() as cur:
            cur.execute(
                "INSERT INTO chat_logs (remote_addr, user_agent, model, request, reply, reasoning, tool_calls, web_search, parsed_files, error) "
                "VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s)",
                (remote_addr, user_agent, model, Json(safe_req), reply_out, reasoning_out, Json(tool_calls_out) if tool_calls_out is not None else None, Json(web_search), Json(parsed_files_meta), error_out)
            )
    finally:
        try:
            pool.putconn(conn)
        except Exception:
            pass

def _api_headers() -> Dict[str, str]:
    if not API_KEY:
        raise RuntimeError("Missing BigModel API key in environment")
    return {"Authorization": f"Bearer {API_KEY}"}

def _bigmodel_url(path: str) -> str:
    p = (path or "").strip()
    if not p:
        return BASE_URL + "/"
    if p.startswith("/"):
        p = p[1:]
    return BASE_URL + "/" + p

def _safe_json(resp: requests.Response) -> Dict[str, Any]:
    try:
        data = resp.json()
        if isinstance(data, dict):
            return data
        return {"data": data}
    except Exception:
        try:
            return {"error": {"message": resp.text}}
        except Exception:
            return {"error": {"message": ""}}

def _bigmodel_post_json(path: str, body: Dict[str, Any], timeout: float) -> Dict[str, Any]:
    url = _bigmodel_url(path)
    headers = _api_headers()
    headers["Content-Type"] = "application/json"
    r = _session.post(url, headers=headers, json=body, timeout=timeout)
    data = _safe_json(r)
    if r.status_code >= 400:
        raise RuntimeError(f"BigModel HTTP {r.status_code}: {json.dumps(data, ensure_ascii=False)}")
    if not isinstance(data, dict):
        raise RuntimeError("Unexpected BigModel response")
    return data

def _bigmodel_post_multipart(path: str, data: Dict[str, Any], files: Dict[str, Tuple[str, Any, str]], timeout: float) -> Dict[str, Any]:
    url = _bigmodel_url(path)
    headers = _api_headers()
    r = _session.post(url, headers=headers, data=data, files=files, timeout=timeout)
    payload = _safe_json(r)
    if r.status_code >= 400:
        raise RuntimeError(f"BigModel HTTP {r.status_code}: {json.dumps(payload, ensure_ascii=False)}")
    if not isinstance(payload, dict):
        raise RuntimeError("Unexpected BigModel response")
    return payload

def _bigmodel_get_json(path: str, timeout: float) -> Dict[str, Any]:
    url = _bigmodel_url(path)
    headers = _api_headers()
    r = _session.get(url, headers=headers, timeout=timeout)
    data = _safe_json(r)
    if r.status_code >= 400:
        raise RuntimeError(f"BigModel HTTP {r.status_code}: {json.dumps(data, ensure_ascii=False)}")
    if not isinstance(data, dict):
        raise RuntimeError("Unexpected BigModel response")
    return data

def _bigmodel_stream_raw(path: str, body: Dict[str, Any], timeout: float) -> Iterable[str]:
    url = _bigmodel_url(path)
    headers = _api_headers()
    headers["Content-Type"] = "application/json"
    with _session.post(url, headers=headers, json=body, timeout=timeout, stream=True) as r:
        if r.status_code >= 400:
            data = _safe_json(r)
            raise RuntimeError(f"BigModel HTTP {r.status_code}: {json.dumps(data, ensure_ascii=False)}")
        for line in r.iter_lines(decode_unicode=True):
            if line is None:
                continue
            s = str(line).strip()
            if not s:
                continue
            yield s

def _parse_sse_data_lines(lines: Iterable[str]) -> Iterable[Union[str, Dict[str, Any]]]:
    for line in lines:
        s = line.strip()
        if not s or s.startswith(":"):
            continue
        if s.startswith("data:"):
            s = s[5:].strip()
        if s == "[DONE]":
            yield "[DONE]"
            break
        try:
            obj = json.loads(s)
            if isinstance(obj, dict):
                yield obj
            else:
                yield {"data": obj}
        except Exception:
            yield {"data": s}

def _guess_file_candidates(filename: str, content_type: Optional[str]) -> List[str]:
    name = filename or "file"
    ext = os.path.splitext(name)[1].lower()
    mt = (content_type or "").lower().strip()
    text_ext = {".txt", ".md", ".markdown", ".json", ".yaml", ".yml", ".csv", ".tsv", ".log", ".ini", ".cfg", ".toml", ".xml", ".html", ".htm"}
    image_ext = {".png", ".jpg", ".jpeg", ".gif", ".bmp", ".webp", ".tiff", ".tif", ".heic", ".heif", ".jp2"}
    doc_ext = {".pdf", ".docx", ".doc", ".pptx", ".ppt", ".xlsx", ".xls", ".rtf", ".odt", ".odp", ".ods"}
    archive_ext = {".zip", ".7z", ".rar", ".tar", ".gz", ".bz2", ".xz"}
    if ext in doc_ext:
        if ext == ".pdf":
            return ["PDF", "WPS"]
        if ext in (".xlsx", ".xls", ".ods"):
            return ["XLSX", "XLS", "WPS"]
        if ext in (".pptx", ".ppt", ".odp"):
            return ["PPTX", "PPT", "WPS"]
        if ext in (".docx", ".doc", ".odt", ".rtf"):
            return ["DOCX", "DOC", "WPS"]
        return ["WPS"]
    if ext in image_ext or mt.startswith("image/"):
        if ext == ".png" or mt == "image/png":
            return ["PNG", "JPEG", "WPS"]
        if ext in (".jpg", ".jpeg") or mt in ("image/jpeg", "image/jpg"):
            return ["JPEG", "JPG", "PNG", "WPS"]
        return ["PNG", "JPEG", "WPS"]
    if ext in text_ext or mt.startswith("text/") or mt in ("application/json", "application/xml"):
        return ["TXT", "MD", "CSV", "WPS"]
    if ext in archive_ext or mt in ("application/zip", "application/x-zip-compressed", "application/x-tar", "application/gzip"):
        return ["ZIP", "WPS", "TXT"]
    if mt.startswith("audio/"):
        return ["AUDIO", "WPS", "TXT"]
    if mt.startswith("video/"):
        return ["VIDEO", "WPS", "TXT"]
    return ["WPS", "TXT"]

def _parse_file_sync(file_storage) -> str:
    filename = getattr(file_storage, "filename", "") or "file"
    ctype = getattr(file_storage, "content_type", None)
    stream = file_storage.stream
    try:
        stream.seek(0, 0)
    except Exception:
        pass
    max_seconds = _env_float("FILE_PARSE_MAX_SECONDS", 240.0)
    poll_seconds = _env_float("FILE_PARSE_POLL_MAX_SECONDS", max_seconds)
    initial_delay = _env_float("FILE_PARSE_INITIAL_DELAY", 1.0)
    max_delay = _env_float("FILE_PARSE_MAX_DELAY", 8.0)
    max_attempts = _env_int("FILE_PARSE_MAX_ATTEMPTS", 0)
    last_error: Optional[str] = None
    candidates = _guess_file_candidates(filename, ctype)
    start = time.time()
    for file_type in candidates:
        try:
            try:
                stream.seek(0, 0)
            except Exception:
                pass
            files = {"file": (filename, stream, ctype or "application/octet-stream")}
            payload = _bigmodel_post_multipart("/files/parser/sync", data={"tool_type": "prime-sync", "file_type": file_type}, files=files, timeout=min(max_seconds, _env_float("FILE_PARSE_REQUEST_TIMEOUT", 180.0)))
            status = str(payload.get("status", "")).lower().strip()
            content = payload.get("content")
            if status == "succeeded" and isinstance(content, str):
                return content
            task_id = payload.get("task_id")
            if not task_id:
                err = payload.get("error") or payload.get("message") or payload
                raise RuntimeError(f"File parse start failed: {json.dumps(err, ensure_ascii=False)}")
            deadline = start + poll_seconds
            delay = initial_delay
            attempts = 0
            while True:
                if max_attempts > 0 and attempts >= max_attempts:
                    break
                now = time.time()
                if now >= deadline:
                    break
                time.sleep(max(0.0, min(delay, max_delay)))
                attempts += 1
                last_payload = _bigmodel_get_json(f"/files/parser/result/{task_id}/text", timeout=_env_float("FILE_PARSE_RESULT_TIMEOUT", 60.0))
                st = str(last_payload.get("status", "")).lower().strip()
                if st == "succeeded" and isinstance(last_payload.get("content"), str):
                    return last_payload["content"]
                if st == "failed":
                    err = last_payload.get("error") or last_payload.get("message") or last_payload
                    raise RuntimeError(f"File parse failed: {json.dumps(err, ensure_ascii=False)}")
                delay = min(max_delay, delay * 1.6 + 0.1)
            err2 = last_payload.get("error") or last_payload.get("message") or last_payload
            raise RuntimeError(f"File parse timeout: {json.dumps(err2, ensure_ascii=False)}")
        except Exception as e:
            last_error = str(e)
            continue
    raise RuntimeError(last_error or "File parse failed")

def _normalize_messages(raw: Any) -> List[Dict[str, Any]]:
    if not isinstance(raw, list) or not raw:
        raise ValueError("messages must be a non-empty array")
    out: List[Dict[str, Any]] = []
    for i, m in enumerate(raw):
        if not isinstance(m, dict):
            raise ValueError(f"messages[{i}] must be an object")
        role = m.get("role")
        content = m.get("content")
        if role not in ("system", "user", "assistant", "tool"):
            raise ValueError(f"messages[{i}].role is invalid")
        if content is None:
            raise ValueError(f"messages[{i}].content is required")
        if not isinstance(content, (str, list, dict)):
            raise ValueError(f"messages[{i}].content has invalid type")
        msg: Dict[str, Any] = {"role": role, "content": content}
        if "name" in m and isinstance(m.get("name"), str):
            msg["name"] = m["name"]
        if "tool_call_id" in m and isinstance(m.get("tool_call_id"), str):
            msg["tool_call_id"] = m["tool_call_id"]
        out.append(msg)
    if not out:
        raise ValueError("messages must contain at least one valid message")
    return out

def _approx_content_chars(content: Any) -> int:
    if isinstance(content, str):
        return len(content)
    if isinstance(content, list):
        total = 0
        for item in content:
            if isinstance(item, dict):
                t = item.get("text")
                if isinstance(t, str):
                    total += len(t)
                else:
                    try:
                        total += len(json.dumps(item, ensure_ascii=False))
                    except Exception:
                        total += len(str(item))
            else:
                total += len(str(item))
        return total
    if isinstance(content, dict):
        try:
            return len(json.dumps(content, ensure_ascii=False))
        except Exception:
            return len(str(content))
    return len(str(content))

def _validate_messages_limits(messages: List[Dict[str, Any]]) -> None:
    max_messages = _env_int("MAX_MESSAGES", 120)
    max_total = _env_int("MAX_TOTAL_MESSAGE_CHARS", 240000)
    max_one = _env_int("MAX_MESSAGE_CHARS", 40000)
    if len(messages) > max_messages:
        raise ValueError("too many messages")
    total = 0
    for i, m in enumerate(messages):
        n = _approx_content_chars(m.get("content"))
        if n > max_one:
            raise ValueError(f"message too large at index {i}")
        total += n
        if total > max_total:
            raise ValueError("messages too large in total")

def _extract_user_text_for_search(messages: List[Dict[str, Any]], max_chars: int, max_user_msgs: int) -> str:
    user_texts: List[str] = []
    for m in reversed(messages):
        if m.get("role") != "user":
            continue
        c = m.get("content")
        if isinstance(c, str):
            t = c.strip()
            if t:
                user_texts.append(t)
        elif isinstance(c, list):
            parts: List[str] = []
            for item in c:
                if isinstance(item, dict) and item.get("type") == "text" and isinstance(item.get("text"), str):
                    tx = item["text"].strip()
                    if tx:
                        parts.append(tx)
            if parts:
                user_texts.append("\n".join(parts))
        if len(user_texts) >= max_user_msgs:
            break
    user_texts.reverse()
    combined = "\n\n".join(user_texts).strip()
    if not combined:
        return ""
    if max_chars > 0 and len(combined) > max_chars:
        cut = combined[:max_chars]
        nl = cut.rfind("\n")
        if nl >= max_chars - 200 and nl > 0:
            cut = cut[:nl]
        return cut
    return combined

def _web_search(query: str, opts: Dict[str, Any]) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    q = (query or "").strip()
    if not q:
        return [], {"enabled": True, "query_used": "", "query_truncated": False}
    max_q = opts.get("query_max_chars")
    if max_q is None:
        max_q = _env_int("WEB_SEARCH_QUERY_MAX_CHARS", 400)
    try:
        max_q = int(max_q)
    except Exception:
        max_q = 400
    truncated = False
    if max_q > 0 and len(q) > max_q:
        q = q[:max_q]
        truncated = True
    count = opts.get("count")
    if count is None:
        count = _env_int("WEB_SEARCH_COUNT", 6)
    try:
        count_i = int(count)
    except Exception:
        count_i = 6
    count_i = max(1, min(count_i, 20))
    recency = str(opts.get("recency") or os.environ.get("WEB_SEARCH_RECENCY_FILTER") or "oneWeek")
    engine = str(opts.get("engine") or os.environ.get("WEB_SEARCH_ENGINE") or "search_std")
