def _parse_request_payload() -> Tuple[Dict[str, Any], List[Tuple[str, str]]]:
    _enforce_request_size()
    parsed_files: List[Tuple[str, str]] = []
    if request.is_json:
        max_json = _env_int("MAX_JSON_BYTES", 2 * 1024 * 1024)
        if request.content_length is not None and request.content_length > max_json:
            raise ValueError("json payload too large")
        req_json = request.get_json(silent=False)
        if not isinstance(req_json, dict):
            raise ValueError("JSON body must be an object")
        return req_json, parsed_files
    ct = (request.content_type or "").lower()
    if "multipart/form-data" in ct or "application/x-www-form-urlencoded" in ct:
        payload = request.form.get("payload")
        if payload is None:
            raise ValueError("missing form field 'payload' containing JSON")
        max_payload = _env_int("MAX_FORM_PAYLOAD_CHARS", 2 * 1024 * 1024)
        if len(payload) > max_payload:
            raise ValueError("payload too large")
        try:
            req_json = json.loads(payload)
        except Exception as e:
            raise ValueError(f"invalid JSON in payload: {str(e)}")
        if not isinstance(req_json, dict):
            raise ValueError("payload JSON must be an object")
        files = request.files.getlist("files")
        if len(files) > _env_int("MAX_FILES", 6):
            raise ValueError("too many files")
        for f in files:
            parsed_files.append((f.filename or "file", _parse_file_sync(f)))
        return req_json, parsed_files
    if request.data:
        max_json = _env_int("MAX_JSON_BYTES", 2 * 1024 * 1024)
        if request.content_length is not None and request.content_length > max_json:
            raise ValueError("json payload too large")
        try:
            req_json = json.loads(request.data.decode("utf-8"))
        except Exception as e:
            raise ValueError(f"invalid JSON body: {str(e)}")
        if not isinstance(req_json, dict):
            raise ValueError("JSON body must be an object")
        return req_json, parsed_files
    raise ValueError("empty request body")

def _latest_user_text(messages: List[Dict[str, Any]]) -> str:
    for m in reversed(messages):
        if m.get("role") != "user":
            continue
        c = m.get("content")
        if isinstance(c, str):
            return c.strip()
        if isinstance(c, list):
            parts: List[str] = []
            for item in c:
                if isinstance(item, dict) and item.get("type") == "text" and isinstance(item.get("text"), str):
                    tx = item["text"].strip()
                    if tx:
                        parts.append(tx)
            return "\n".join(parts).strip()
        if isinstance(c, dict):
            try:
                return json.dumps(c, ensure_ascii=False)
            except Exception:
                return str(c)
    return ""

