    with _db_lock:
        if _db_pool is not None:
            return _db_pool
        if not _db_can_retry_now():
            return None
        try:
            minconn = max(0, _env_int("PGPOOL_MIN", 1))
            maxconn = max(1, _env_int("PGPOOL_MAX", 8))
            if minconn > maxconn:
                minconn = maxconn
            dsn = _pg_dsn()
            pool = ThreadedConnectionPool(minconn, maxconn, dsn=dsn)
            conn = pool.getconn()
            try:
                conn.autocommit = True
                with conn.cursor() as cur:
                    cur.execute(
                        "CREATE TABLE IF NOT EXISTS chat_logs ("
                        "id BIGSERIAL PRIMARY KEY,"
                        "created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),"
                        "remote_addr TEXT,"
                        "user_agent TEXT,"
                        "model TEXT,"
                        "request JSONB NOT NULL,"
                        "reply TEXT,"
                        "reasoning TEXT,"
                        "tool_calls JSONB,"
                        "web_search JSONB,"
                        "parsed_files JSONB,"
                        "error TEXT)"
                    )
                    cur.execute("CREATE INDEX IF NOT EXISTS chat_logs_created_at_idx ON chat_logs (created_at DESC)")
                    cur.execute("CREATE INDEX IF NOT EXISTS chat_logs_model_idx ON chat_logs (model)")
            finally:
                pool.putconn(conn)
            _db_pool = pool
            _db_last_init_error = None
            _db_next_retry_ts = 0.0
            return _db_pool
        except Exception as e:
            _db_pool = None
            _db_last_init_error = str(e)
            _set_db_retry_backoff()
            return None

def _get_db_pool() -> Optional[Any]:
    return _db_pool if _db_pool is not None else _db_init_pool()

def _db_log_chat(model: str, req_json: Dict[str, Any], reply: Optional[str], reasoning: Optional[str], tool_calls: Optional[Any], web_search: List[Dict[str, Any]], parsed_files_meta: List[Dict[str, Any]], error: Optional[str], remote_addr: Optional[str], user_agent: Optional[str]) -> None:
    pool = _get_db_pool()
    if pool is None:
        return
    max_req_chars = _env_int("MAX_DB_REQUEST_CHARS", 400000)
    max_text = _env_int("MAX_DB_TEXT_CHARS", 100000)
    max_err = _env_int("MAX_DB_ERROR_CHARS", 20000)
    def _safe_request_obj(obj: Any) -> Any:
        if obj is None:
            return {}
        try:
            s = json.dumps(obj, ensure_ascii=False, separators=(",", ":"))
            if len(s) <= max_req_chars:
                return obj
            return {"truncated": True, "raw": s[:max_req_chars]}
        except Exception:
            try:
                s2 = str(obj)
                return {"truncated": True, "raw": s2[:max_req_chars]}
            except Exception:
                return {"truncated": True, "raw": None}
    safe_req = _safe_request_obj(req_json)
    reply_out = reply if reply is None or len(reply) <= max_text else reply[:max_text]
    reasoning_out = reasoning if reasoning is None or len(reasoning) <= max_text else reasoning[:max_text]
    error_out = error if error is None or len(error) <= max_err else error[:max_err]
    tool_calls_out = tool_calls
    try:
        if tool_calls_out is not None:
            json.dumps(tool_calls_out, ensure_ascii=False)
    except Exception:
        tool_calls_out = {"unserializable": True}
    conn = pool.getconn()
    try:
        conn.autocommit = True
        with conn.cursor() as cur:
            cur.execute(
                "INSERT INTO chat_logs (remote_addr, user_agent, model, request, reply, reasoning, tool_calls, web_search, parsed_files, error) "
                "VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s)",
                (remote_addr, user_agent, model, Json(safe_req), reply_out, reasoning_out, Json(tool_calls_out) if tool_calls_out is not None else None, Json(web_search), Json(parsed_files_meta), error_out)
            )
    finally:
        try:
            pool.putconn(conn)
        except Exception:
            pass

def _api_headers() -> Dict[str, str]:
    if not API_KEY:
        raise RuntimeError("Missing BigModel API key in environment")
    return {"Authorization": f"Bearer {API_KEY}"}

def _bigmodel_url(path: str) -> str:
    p = (path or "").strip()
    if not p:
        return BASE_URL + "/"
    if p.startswith("/"):
        p = p[1:]
    return BASE_URL + "/" + p

def _safe_json(resp: requests.Response) -> Dict[str, Any]:
    try:
        data = resp.json()
        if isinstance(data, dict):
            return data
        return {"data": data}
    except Exception:
        try:
            return {"error": {"message": resp.text}}
        except Exception:
            return {"error": {"message": ""}}

def _bigmodel_post_json(path: str, body: Dict[str, Any], timeout: float) -> Dict[str, Any]:
    url = _bigmodel_url(path)
    headers = _api_headers()
    headers["Content-Type"] = "application/json"
    r = _session.post(url, headers=headers, json=body, timeout=timeout)
    data = _safe_json(r)
    if r.status_code >= 400:
        raise RuntimeError(f"BigModel HTTP {r.status_code}: {json.dumps(data, ensure_ascii=False)}")
    if not isinstance(data, dict):
        raise RuntimeError("Unexpected BigModel response")
    return data

def _bigmodel_post_multipart(path: str, data: Dict[str, Any], files: Dict[str, Tuple[str, Any, str]], timeout: float) -> Dict[str, Any]:
    url = _bigmodel_url(path)
    headers = _api_headers()
    r = _session.post(url, headers=headers, data=data, files=files, timeout=timeout)
    payload = _safe_json(r)
    if r.status_code >= 400:
        raise RuntimeError(f"BigModel HTTP {r.status_code}: {json.dumps(payload, ensure_ascii=False)}")
    if not isinstance(payload, dict):
        raise RuntimeError("Unexpected BigModel response")
    return payload

def _bigmodel_get_json(path: str, timeout: float) -> Dict[str, Any]:
    url = _bigmodel_url(path)
    headers = _api_headers()
    r = _session.get(url, headers=headers, timeout=timeout)
    data = _safe_json(r)
    if r.status_code >= 400:
        raise RuntimeError(f"BigModel HTTP {r.status_code}: {json.dumps(data, ensure_ascii=False)}")
    if not isinstance(data, dict):
        raise RuntimeError("Unexpected BigModel response")
    return data

def _bigmodel_stream_raw(path: str, body: Dict[str, Any], timeout: float) -> Iterable[str]:
    url = _bigmodel_url(path)
    headers = _api_headers()
    headers["Content-Type"] = "application/json"
    with _session.post(url, headers=headers, json=body, timeout=timeout, stream=True) as r:
        if r.status_code >= 400:
            data = _safe_json(r)
            raise RuntimeError(f"BigModel HTTP {r.status_code}: {json.dumps(data, ensure_ascii=False)}")
        for line in r.iter_lines(decode_unicode=True):
            if line is None:
                continue
            s = str(line).strip()
            if not s:
                continue
            yield s

def _parse_sse_data_lines(lines: Iterable[str]) -> Iterable[Union[str, Dict[str, Any]]]:
    for line in lines:
        s = line.strip()
        if not s or s.startswith(":"):
            continue
        if s.startswith("data:"):
            s = s[5:].strip()
        if s == "[DONE]":
            yield "[DONE]"
            break
        try:
            obj = json.loads(s)
            if isinstance(obj, dict):
                yield obj
            else:
                yield {"data": obj}
        except Exception:
            yield {"data": s}

def _guess_file_candidates(filename: str, content_type: Optional[str]) -> List[str]:
    name = filename or "file"
    ext = os.path.splitext(name)[1].lower()
    mt = (content_type or "").lower().strip()
    text_ext = {".txt", ".md", ".markdown", ".json", ".yaml", ".yml", ".csv", ".tsv", ".log", ".ini", ".cfg", ".toml", ".xml", ".html", ".htm"}
    image_ext = {".png", ".jpg", ".jpeg", ".gif", ".bmp", ".webp", ".tiff", ".tif", ".heic", ".heif", ".jp2"}
    doc_ext = {".pdf", ".docx", ".doc", ".pptx", ".ppt", ".xlsx", ".xls", ".rtf", ".odt", ".odp", ".ods"}
    archive_ext = {".zip", ".7z", ".rar", ".tar", ".gz", ".bz2", ".xz"}
    if ext in doc_ext:
        if ext == ".pdf":
            return ["PDF", "WPS"]
        if ext in (".xlsx", ".xls", ".ods"):
            return ["XLSX", "XLS", "WPS"]
        if ext in (".pptx", ".ppt", ".odp"):
            return ["PPTX", "PPT", "WPS"]
        if ext in (".docx", ".doc", ".odt", ".rtf"):
            return ["DOCX", "DOC", "WPS"]
        return ["WPS"]
    if ext in image_ext or mt.startswith("image/"):
        if ext == ".png" or mt == "image/png":
            return ["PNG", "JPEG", "WPS"]
        if ext in (".jpg", ".jpeg") or mt in ("image/jpeg", "image/jpg"):
            return ["JPEG", "JPG", "PNG", "WPS"]
        return ["PNG", "JPEG", "WPS"]
    if ext in text_ext or mt.startswith("text/") or mt in ("application/json", "application/xml"):
        return ["TXT", "MD", "CSV", "WPS"]
    if ext in archive_ext or mt in ("application/zip", "application/x-zip-compressed", "application/x-tar", "application/gzip"):
        return ["ZIP", "WPS", "TXT"]
    if mt.startswith("audio/"):
        return ["AUDIO", "WPS", "TXT"]
    if mt.startswith("video/"):
        return ["VIDEO", "WPS", "TXT"]
    return ["WPS", "TXT"]

def _parse_file_sync(file_storage) -> str:
    filename = getattr(file_storage, "filename", "") or "file"
    ctype = getattr(file_storage, "content_type", None)
    stream = file_storage.stream
    try:
        stream.seek(0, 0)
    except Exception:
        pass
    max_seconds = _env_float("FILE_PARSE_MAX_SECONDS", 240.0)
    poll_seconds = _env_float("FILE_PARSE_POLL_MAX_SECONDS", max_seconds)
    initial_delay = _env_float("FILE_PARSE_INITIAL_DELAY", 1.0)
    max_delay = _env_float("FILE_PARSE_MAX_DELAY", 8.0)
    max_attempts = _env_int("FILE_PARSE_MAX_ATTEMPTS", 0)
    last_error: Optional[str] = None
    candidates = _guess_file_candidates(filename, ctype)
    start = time.time()
    for file_type in candidates:
        try:
            try:
                stream.seek(0, 0)
            except Exception:
                pass
            files = {"file": (filename, stream, ctype or "application/octet-stream")}
            payload = _bigmodel_post_multipart("/files/parser/sync", data={"tool_type": "prime-sync", "file_type": file_type}, files=files, timeout=min(max_seconds, _env_float("FILE_PARSE_REQUEST_TIMEOUT", 180.0)))
            status = str(payload.get("status", "")).lower().strip()
            content = payload.get("content")
            if status == "succeeded" and isinstance(content, str):
                return content
            task_id = payload.get("task_id")
            if not task_id:
                err = payload.get("error") or payload.get("message") or payload
                raise RuntimeError(f"File parse start failed: {json.dumps(err, ensure_ascii=False)}")
            deadline = start + poll_seconds
            delay = initial_delay
            attempts = 0
            while True:
                if max_attempts > 0 and attempts >= max_attempts:
                    break
                now = time.time()
                if now >= deadline:
                    break
                time.sleep(max(0.0, min(delay, max_delay)))
                attempts += 1
                last_payload = _bigmodel_get_json(f"/files/parser/result/{task_id}/text", timeout=_env_float("FILE_PARSE_RESULT_TIMEOUT", 60.0))
                st = str(last_payload.get("status", "")).lower().strip()
                if st == "succeeded" and isinstance(last_payload.get("content"), str):
                    return last_payload["content"]
                if st == "failed":
                    err = last_payload.get("error") or last_payload.get("message") or last_payload
                    raise RuntimeError(f"File parse failed: {json.dumps(err, ensure_ascii=False)}")
                delay = min(max_delay, delay * 1.6 + 0.1)
            err2 = last_payload.get("error") or last_payload.get("message") or last_payload
            raise RuntimeError(f"File parse timeout: {json.dumps(err2, ensure_ascii=False)}")
        except Exception as e:
            last_error = str(e)
            continue
    raise RuntimeError(last_error or "File parse failed")

def _normalize_messages(raw: Any) -> List[Dict[str, Any]]:
    if not isinstance(raw, list) or not raw:
        raise ValueError("messages must be a non-empty array")
    out: List[Dict[str, Any]] = []
    for i, m in enumerate(raw):
        if not isinstance(m, dict):
            raise ValueError(f"messages[{i}] must be an object")
        role = m.get("role")
        content = m.get("content")
        if role not in ("system", "user", "assistant", "tool"):
            raise ValueError(f"messages[{i}].role is invalid")
        if content is None:
            raise ValueError(f"messages[{i}].content is required")
        if not isinstance(content, (str, list, dict)):
            raise ValueError(f"messages[{i}].content has invalid type")
        msg: Dict[str, Any] = {"role": role, "content": content}
        if "name" in m and isinstance(m.get("name"), str):
            msg["name"] = m["name"]
        if "tool_call_id" in m and isinstance(m.get("tool_call_id"), str):
            msg["tool_call_id"] = m["tool_call_id"]
        out.append(msg)
    if not out:
        raise ValueError("messages must contain at least one valid message")
    return out

def _approx_content_chars(content: Any) -> int:
    if isinstance(content, str):
        return len(content)
    if isinstance(content, list):
        total = 0
        for item in content:
            if isinstance(item, dict):
                t = item.get("text")
                if isinstance(t, str):
                    total += len(t)
                else:
                    try:
                        total += len(json.dumps(item, ensure_ascii=False))
                    except Exception:
                        total += len(str(item))
            else:
                total += len(str(item))
        return total
    if isinstance(content, dict):
        try:
            return len(json.dumps(content, ensure_ascii=False))
        except Exception:
            return len(str(content))
    return len(str(content))

def _validate_messages_limits(messages: List[Dict[str, Any]]) -> None:
    max_messages = _env_int("MAX_MESSAGES", 120)
    max_total = _env_int("MAX_TOTAL_MESSAGE_CHARS", 240000)
    max_one = _env_int("MAX_MESSAGE_CHARS", 40000)
    if len(messages) > max_messages:
        raise ValueError("too many messages")
    total = 0
    for i, m in enumerate(messages):
        n = _approx_content_chars(m.get("content"))
        if n > max_one:
            raise ValueError(f"message too large at index {i}")
        total += n
        if total > max_total:
            raise ValueError("messages too large in total")

def _extract_user_text_for_search(messages: List[Dict[str, Any]], max_chars: int, max_user_msgs: int) -> str:
    user_texts: List[str] = []
    for m in reversed(messages):
        if m.get("role") != "user":
            continue
        c = m.get("content")
        if isinstance(c, str):
            t = c.strip()
            if t:
                user_texts.append(t)
        elif isinstance(c, list):
            parts: List[str] = []
            for item in c:
                if isinstance(item, dict) and item.get("type") == "text" and isinstance(item.get("text"), str):
                    tx = item["text"].strip()
                    if tx:
                        parts.append(tx)
            if parts:
                user_texts.append("\n".join(parts))
        if len(user_texts) >= max_user_msgs:
            break
    user_texts.reverse()
    combined = "\n\n".join(user_texts).strip()
    if not combined:
        return ""
    if max_chars > 0 and len(combined) > max_chars:
        cut = combined[:max_chars]
        nl = cut.rfind("\n")
        if nl >= max_chars - 200 and nl > 0:
            cut = cut[:nl]
        return cut
    return combined

def _web_search(query: str, opts: Dict[str, Any]) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    q = (query or "").strip()
    if not q:
        return [], {"enabled": True, "query_used": "", "query_truncated": False}
    max_q = opts.get("query_max_chars")
    if max_q is None:
        max_q = _env_int("WEB_SEARCH_QUERY_MAX_CHARS", 400)
    try:
        max_q = int(max_q)
    except Exception:
        max_q = 400
    truncated = False
    if max_q > 0 and len(q) > max_q:
        q = q[:max_q]
        truncated = True
    count = opts.get("count")
    if count is None:
        count = _env_int("WEB_SEARCH_COUNT", 6)
    try:
        count_i = int(count)
    except Exception:
        count_i = 6
    count_i = max(1, min(count_i, 20))
    recency = str(opts.get("recency") or os.environ.get("WEB_SEARCH_RECENCY_FILTER") or "oneWeek")
    engine = str(opts.get("engine") or os.environ.get("WEB_SEARCH_ENGINE") or "search_std")
    content_size = str(opts.get("content_size") or os.environ.get("WEB_SEARCH_CONTENT_SIZE") or "medium")
    search_intent = opts.get("search_intent")
    if search_intent is None:
        search_intent = _env_bool("WEB_SEARCH_INTENT", False)
    else:
        search_intent = bool(search_intent)
    body = {
        "search_query": q,
        "search_engine": engine,
        "search_intent": search_intent,
        "count": count_i,
        "search_recency_filter": recency,
        "content_size": content_size,
    }
    timeout = _env_float("WEB_SEARCH_TIMEOUT", 60.0)
    data = _bigmodel_post_json("/web_search", body, timeout=timeout)
    results = data.get("search_result")
    out: List[Dict[str, Any]] = []
    if isinstance(results, list):
        for r in results:
            if isinstance(r, dict):
                out.append(r)
    meta = {
        "enabled": True, "query_used": q, "query_truncated": truncated,
        "count": count_i, "recency": recency, "engine": engine,
        "content_size": content_size, "search_intent": search_intent,
    }
    return out, meta

def _truncate_text_preserving_boundary(text: str, limit: int) -> str:
    if limit <= 0 or len(text) <= limit:
        return text
    cut = text[:limit]
    for sep in ("\n\n", "\n", ". ", " "):
        idx = cut.rfind(sep)
        if idx >= max(0, limit - 400) and idx > 0:
            return cut[:idx].rstrip()
    return cut.rstrip()

def _build_context_message(search_results: List[Dict[str, Any]], parsed_files: List[Tuple[str, str]], limits: Dict[str, Any]) -> Optional[Dict[str, str]]:
    max_total = int(limits.get("max_total") or _env_int("MAX_CONTEXT_CHARS", 180000))
    max_file_chars = int(limits.get("max_file_chars") or _env_int("MAX_FILE_TEXT_CHARS", 60000))
    max_search_item_chars = int(limits.get("max_search_item_chars") or _env_int("MAX_SEARCH_ITEM_CHARS", 5000))
    max_search_items = int(limits.get("max_search_items") or _env_int("MAX_SEARCH_ITEMS", 6))
    blocks: List[str] = []
    used = 0
    if parsed_files:
        file_blocks: List[str] = []
        for name, text in parsed_files:
            header = f"=== FILE: {name} ===\n"
            t = _truncate_text_preserving_boundary(text, max_file_chars)
            file_blocks.append(header + t)
        fb = "\n\n".join(file_blocks)
        fb = _truncate_text_preserving_boundary(fb, max_total)
        if fb:
            blocks.append(fb)
            used += len(fb)
    if search_results:
        items: List[str] = []
        for i, r in enumerate(search_results[:max_search_items], 1):
            title = str(r.get("title", "")).strip()
            link = str(r.get("link", "")).strip()
            publish_date = str(r.get("publish_date", "")).strip()
            content = str(r.get("content", "")).strip()
            media = str(r.get("media", "")).strip()
            head = f"[{i}] {title}"
            meta = " | ".join([x for x in (media, publish_date, link) if x])
            if meta:
                head = head + " — " + meta
            if content:
                body = _truncate_text_preserving_boundary(content, max_search_item_chars)
                items.append(head + "\n" + body)
            else:
                items.append(head)
        sb = "=== WEB SEARCH RESULTS ===\n" + "\n\n".join(items)
        remaining = max_total - used
        if remaining > 0:
            sb = _truncate_text_preserving_boundary(sb, remaining)
            if sb:
                blocks.append(sb)
    if not blocks:
        return None
    combined = _truncate_text_preserving_boundary("\n\n".join(blocks), max_total)
    if not combined:
        return None
    return {"role": "system", "content": combined}

_ALLOWED_EXTRA_KEYS = {
    "temperature", "top_p", "max_tokens", "do_sample", "stop", "presence_penalty",
    "frequency_penalty", "logit_bias", "seed", "response_format", "tools",
    "tool_choice", "parallel_tool_calls", "user", "n",
}

def _create_completion_body(req: Dict[str, Any], messages: List[Dict[str, Any]], context_msg: Optional[Dict[str, Any]], stream: bool) -> Dict[str, Any]:
    model = "glm-5"
    is_search = bool(req.get("web_search", False))
    is_thinking = bool(req.get("thinking", False))
    body: Dict[str, Any] = {"model": model, "stream": stream}
    if is_search or bool(req.get("search_enabled", False)):
        body["tools"] = body.get("tools", [])
        body["tools"].append({"type": "web_search", "web_search": {"enable": True}})
    sys_parts: List[str] = []
    if context_msg and isinstance(context_msg.get("content"), str) and context_msg["content"].strip():
        sys_parts.append(context_msg["content"].strip())
    non_system: List[Dict[str, Any]] = []
    for m in messages:
        if m.get("role") == "system":
            c = m.get("content")
            if isinstance(c, str) and c.strip():
                sys_parts.append(c.strip())
            elif isinstance(c, (dict, list)):
                try:
                    sys_parts.append(json.dumps(c, ensure_ascii=False))
                except Exception:
                    sys_parts.append(str(c))
        else:
            non_system.append(m)
    final_messages: List[Dict[str, Any]] = []
    if sys_parts:
        final_messages.append({"role": "system", "content": "\n\n".join(sys_parts)})
    final_messages.extend(non_system)
    body["messages"] = final_messages
    if stream:
        body["stream"] = True
    if "thinking" in req:
        thinking = req.get("thinking")
        if thinking is None:
            pass
        elif isinstance(thinking, dict):
            body["thinking"] = thinking
        else:
            raise ValueError("thinking must be an object or null")
    extra_body = req.get("extra_body") if isinstance(req.get("extra_body"), dict) else {}
    for k in list(extra_body.keys()):
        if k not in _ALLOWED_EXTRA_KEYS:
            extra_body.pop(k, None)
    for k, v in extra_body.items():
        body[k] = v
    for k in _ALLOWED_EXTRA_KEYS:
        if k in req:
            body[k] = req[k]
    if "max_tokens" not in body:
        body["max_tokens"] = _env_int("DEFAULT_MAX_TOKENS", 4096)
    return body

def _extract_tool_calls_from_response(data: Dict[str, Any]) -> Any:
    try:
        choices = data.get("choices") or []
        if not choices:
            return None
        first = choices[0] if isinstance(choices[0], dict) else {}
        msg = first.get("message") or {}
        if isinstance(msg, dict) and "tool_calls" in msg:
            return msg.get("tool_calls")
        return None
    except Exception:
        return None

def _extract_reply_and_reasoning(data: Dict[str, Any]) -> Tuple[Optional[Any], Optional[Any]]:
    try:
        choices = data.get("choices") or []
        if not choices:
            return None, None
        first = choices[0] if isinstance(choices[0], dict) else {}
        msg = first.get("message") or {}
        if not isinstance(msg, dict):
            return None, None
        return msg.get("content"), msg.get("reasoning_content")
    except Exception:
        return None, None

def _client_ip() -> str:
    xff = request.headers.get("X-Forwarded-For")
    if xff:
        return xff.split(",")[0].strip()
    return request.remote_addr or "unknown"

_rate_lock = threading.Lock()
_rate_state: Dict[str, Dict[str, Any]] = {}

def _rate_limit_check() -> Optional[Tuple[Response, int]]:
    if not _env_bool("RATE_LIMIT_ENABLED", True):
        return None
    refill_per_sec = max(0.01, _env_float("RATE_LIMIT_REFILL_PER_SEC", 1.0))
    burst = max(1, _env_int("RATE_LIMIT_BURST", _env_int("RATE_LIMIT_CAPACITY", 60)))
    ip = _client_ip()
    now = time.time()
    with _rate_lock:
        st = _rate_state.get(ip)
        if st is None:
            st = {"tokens": float(burst), "ts": now}
            _rate_state[ip] = st
        else:
            elapsed = max(0.0, now - float(st.get("ts", now)))
            st["ts"] = now
            st["tokens"] = min(float(burst), float(st.get("tokens", burst)) + elapsed * refill_per_sec)
        if float(st["tokens"]) < 1.0:
            retry = int(max(1.0, (1.0 - float(st["tokens"])) / refill_per_sec))
            body = {"error": {"message": "rate limit exceeded", "retry_after_seconds": retry}}
            resp = jsonify(body)
            resp.headers["Retry-After"] = str(retry)
            return resp, 429
        st["tokens"] = float(st["tokens"]) - 1.0
        if len(_rate_state) > _env_int("RATE_LIMIT_MAX_KEYS", 5000):
            cutoff = now - _env_float("RATE_LIMIT_MAX_IDLE_SECONDS", 600.0)
            for k in list(_rate_state.keys()):
                if float(_rate_state[k].get("ts", 0.0)) < cutoff:
                    _rate_state.pop(k, None)
    return None

def _json_error(message: str, status: int = 400, detail: Any = None) -> Tuple[Response, int]:
    body: Dict[str, Any] = {"error": {"message": message}}
    if detail is not None:
        body["error"]["detail"] = detail
    return jsonify(body), status

def _enforce_request_size() -> None:
    cl = request.content_length
    if cl is None:
        return
    if cl > _env_int("MAX_REQUEST_BYTES", 5 * 1024 * 1024):
        raise ValueError("request too large")

def _parse_request_payload() -> Tuple[Dict[str, Any], List[Tuple[str, str]]]:
    _enforce_request_size()
    parsed_files: List[Tuple[str, str]] = []
    if request.is_json:
        max_json = _env_int("MAX_JSON_BYTES", 2 * 1024 * 1024)
        if request.content_length is not None and request.content_length > max_json:
            raise ValueError("json payload too large")
        req_json = request.get_json(silent=False)
        if not isinstance(req_json, dict):
            raise ValueError("JSON body must be an object")
        return req_json, parsed_files
    ct = (request.content_type or "").lower()
    if "multipart/form-data" in ct or "application/x-www-form-urlencoded" in ct:
        payload = request.form.get("payload")
        if payload is None:
            raise ValueError("missing form field 'payload' containing JSON")
        max_payload = _env_int("MAX_FORM_PAYLOAD_CHARS", 2 * 1024 * 1024)
        if len(payload) > max_payload:
            raise ValueError("payload too large")
        try:
            req_json = json.loads(payload)
        except Exception as e:
            raise ValueError(f"invalid JSON in payload: {str(e)}")
        if not isinstance(req_json, dict):
            raise ValueError("payload JSON must be an object")
        files = request.files.getlist("files")
        if len(files) > _env_int("MAX_FILES", 6):
            raise ValueError("too many files")
        for f in files:
            parsed_files.append((f.filename or "file", _parse_file_sync(f)))
        return req_json, parsed_files
    if request.data:
        max_json = _env_int("MAX_JSON_BYTES", 2 * 1024 * 1024)
        if request.content_length is not None and request.content_length > max_json:
            raise ValueError("json payload too large")
        try:
            req_json = json.loads(request.data.decode("utf-8"))
        except Exception as e:
            raise ValueError(f"invalid JSON body: {str(e)}")
        if not isinstance(req_json, dict):
            raise ValueError("JSON body must be an object")
        return req_json, parsed_files
    raise ValueError("empty request body")

def _latest_user_text(messages: List[Dict[str, Any]]) -> str:
    for m in reversed(messages):
        if m.get("role") != "user":
            continue
        c = m.get("content")
        if isinstance(c, str):
            return c.strip()
        if isinstance(c, list):
            parts: List[str] = []
            for item in c:
                if isinstance(item, dict) and item.get("type") == "text" and isinstance(item.get("text"), str):
                    tx = item["text"].strip()
                    if tx:
                        parts.append(tx)
            return "\n".join(parts).strip()
        if isinstance(c, dict):
            try:
                return json.dumps(c, ensure_ascii=False)
            except Exception:
                return str(c)
    return ""

_TRIVIAL_RE = re.compile(r"^\s*([.!?…,\-–—_]*\s*)*(szia|hell[oó]|hi|hey|yo|cs[áa]|cs[áa]ó|szeva|hali|helloszia|ok|okay|k(ö|o)szi|thx|thanks|sup)\s*([.!?…,\-–—_]*)\s*$", re.IGNORECASE)
_ONLY_EMOJI_RE = re.compile(r"^[\s\U0001F300-\U0001FAFF\u2600-\u27BF]+$")

def _is_trivial_message(text: str) -> bool:
    t = (text or "").strip()
    if not t:
        return True
    if "\n" in t:
        return False
    if "http://" in t.lower() or "https://" in t.lower():
        return False
    if len(t) <= 16 and _TRIVIAL_RE.match(t):
        return True
    if len(t) <= 16 and _ONLY_EMOJI_RE.match(t):
        return True
    if len(t) <= 6 and t.isalpha():
        return True
    return False

def _should_auto_web_search(text: str, has_files: bool) -> bool:
    if has_files:
        return False
    t = (text or "").strip()
    if not t:
        return False
    tl = t.lower()
    if "http://" in tl or "https://" in tl:
        return True
    if any(k in tl for k in ("legfrissebb", "friss", "mai", "ma ", "today", "yesterday", "tegnap", "most", "jelenleg", "aktuális", "hír", "news", "ár", "price", "rate", "árfolyam", "weather", "időjárás")):
        return True
    if "?" in t:
        return True
    if len(t) >= 220:
        return True
    return False

def _apply_speed_profile(body: Dict[str, Any], trivial: bool) -> Dict[str, Any]:
    if not trivial:
        return body
    cap = _env_int("TRIVIAL_MAX_TOKENS", 256)
    try:
        cur = int(body.get("max_tokens") or cap)
    except Exception:
        cur = cap
    body["max_tokens"] = max(16, min(cur, cap))
    if "temperature" not in body:
        body["temperature"] = float(os.environ.get("TRIVIAL_TEMPERATURE", "0.7"))
    if "thinking" in body:
        body.pop("thinking", None)
    return body

def _coerce_thinking(req_json: Dict[str, Any]) -> None:
    if "thinking" in req_json:
        tv = req_json.get("thinking")
        if isinstance(tv, bool):
            if tv:
                req_json["thinking"] = {"enabled": True}
            else:
                req_json["thinking"] = None
        elif tv is not None and not isinstance(tv, dict):
            raise ValueError("thinking must be an object, boolean, or null")
    if "thinking" not in req_json and "thinking_enabled" in req_json:
        te = req_json.get("thinking_enabled")
        if isinstance(te, bool):
            if te:
                req_json["thinking"] = {"enabled": True}
        else:
            if te:
                req_json["thinking"] = {"enabled": True}

